python
def undoDrawerPeakTicket(readings, k):
    a=readings
    out=[]
    for x in a:
        if x>=0: out.append(x)
        else:
            for _ in range(min(-x,len(out))): out.pop()
    return max(out,default=0)


java
class Solution {
  public int undoDrawerPeakTicket(int[] readings, int k) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {for(int x:a){if(x>=0)out.add(x);else for(int i=0;i<-x&&!out.isEmpty();i++)out.remove(out.size()-1);}}
    int answer=out.isEmpty()?0:out.get(0);for(int x:out)answer=Math.max(answer,x);return answer;
  }
}
